package com.hbm.client.generator.stirling;
import com.hbm.client.model.*;import com.hbm.machine.generator.stirling.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;
/** Exact original Forge stirling.obj groups,pivots and UV inset, including cogless remaining mechanism. */
public final class StirlingRenderer implements BlockEntityRenderer<StirlingBlockEntity> {
 static final ResourceLocation MODEL=ResourceLocation.parse("hbm:models/machines/stirling.obj");public StirlingRenderer(BlockEntityRendererProvider.Context context){}static WavefrontMesh mesh(){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);}static ResourceLocation texture(int gear){return ResourceLocation.parse("hbm:textures/models/machines/"+(gear==0?"stirling":gear==2?"stirling_creative":"stirling_steel")+".png");}static void part(String name,int gear,PoseStack pose,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.render(mesh(),pose,buffers.getBuffer(RenderType.entityCutout(texture(gear))),light,overlay,0xffffffff,LegacyObjRenderer.Convention.FORGE,WavefrontMesh.legacyPart(name));}
 static void common(float rotation,boolean cog,int gear,PoseStack pose,MultiBufferSource buffers,int light,int overlay){part("Base",gear,pose,buffers,light,overlay);if(cog){pose.pushPose();pose.translate(0,1.375,0);pose.mulPose(Axis.ZN.rotationDegrees(rotation));pose.translate(0,-1.375,0);part("Cog",gear,pose,buffers,light,overlay);pose.popPose();}pose.pushPose();pose.translate(0,1.375,.25);pose.mulPose(Axis.XP.rotationDegrees(rotation*2+3));pose.translate(0,-1.375,-.25);part("CogSmall",gear,pose,buffers,light,overlay);pose.popPose();pose.pushPose();pose.translate(Math.sin(rotation*Math.PI/90D)*.25+.125,0,0);part("Piston",gear,pose,buffers,light,overlay);pose.popPose();}
 @Override public void render(StirlingBlockEntity machine,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){float yaw=switch(DummyableBlock.facing(machine.getBlockState())){case SOUTH->0;case EAST->90;case NORTH->180;default->270;};LegacyContactShadows.render(machine,mesh(),new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(yaw)),pose,buffers);pose.pushPose();pose.translate(.5,0,.5);pose.mulPose(Axis.YP.rotationDegrees(yaw));common(machine.lastSpin+(machine.spin-machine.lastSpin)*partial,machine.hasCog,machine.kind.gear,pose,buffers,light,overlay);pose.popPose();}
 @Override public boolean shouldRenderOffScreen(StirlingBlockEntity machine){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(StirlingBlockEntity machine){var p=machine.getBlockPos();return new AABB(p.getX()-1,p.getY(),p.getZ()-1,p.getX()+2,p.getY()+2,p.getZ()+2);}
}
